async function loadVehicleCatalog(){const brand=brandSelect.value===otherValue?customBrand.value.trim():brandSelect.value,model=modelSelect.value===otherValue?customModel.value.trim():modelSelect.value,year=+listingForm.elements.year.value;if(!brand||!model){vehicleCatalog=[];renderCatalogHints();return}const client=window.vklucheAuth?.getClient();if(!client)return;let query=client.from('vehicle_catalog').select('*').ilike('brand',brand).ilike('model',model).limit(100);if(year)query=query.lte('year_from',year).gte('year_to',year);const{data,error}=await query;vehicleCatalog=error?[]:data||[];renderCatalogHints()}
