async function adminContext(){const client=window.vklucheAuth?.getClient(),user=window.vklucheAuth?.getUser();if(!client||!user)return null;const{data}=await client.from('profiles').select('role,account_type').eq('id',user.id).maybeSingle();const{data:member}=await client.from('organization_members').select('organization_id,member_role').eq('user_id',user.id).eq('active',true).in('member_role',['owner','administrator','manager']).limit(1).maybeSingle();if(member)return{client,user,admin:data?.role==='admin',organizationId:member.organization_id};if(data?.role==='admin')return{client,user,admin:true,organizationId:null};return null}
async function loadFeedSources(){feedSources.innerHTML='';autoFeedForm.classList.remove('allowed');autoFeedNotice.style.display='block';const context=await adminContext();if(!context){autoFeedNotice.textContent=window.vklucheAuth?.getUser()?'Создайте компанию или получите права менеджера для управления фидами.':'Войдите, чтобы управлять источниками.';return}autoFeedForm.classList.add('allowed');autoFeedNotice.style.display='none';let query=context.client.from('feed_sources').select('*').order('created_at',{ascending:false});if(!context.admin)query=query.eq('organization_id',context.organizationId);const{data,error}=await query;if(error){autoFeedNotice.style.display='block';autoFeedNotice.textContent=`Не удалось загрузить источники: ${error.message}`;return}feedSources.innerHTML=data.length?data.map(source=>`<div class="feed-source"><span><b>${escapeHtml(source.name)}</b><small>${source.interval_minutes} мин · ${source.last_run_at?`последняя проверка ${new Date(source.last_run_at).toLocaleString('ru-RU')}`:'ещё не запускался'}</small><small class="feed-source-status ${source.last_status||''}">${source.last_status==='success'?'Загружен успешно':source.last_error?escapeHtml(source.last_error):'Ожидает запуска'}</small></span><button type="button" data-sync-feed="${source.id}">Загрузить сейчас</button></div>`).join(''):'<div class="auto-feed-login">Автоматических источников пока нет.</div>'}
