function auctionCard(car){const auction=car.auction,scheduled=auction.status==='scheduled',active=auction.status==='active',completed=['deal_confirmed','no_sale','cancelled'].includes(auction.status),target=scheduled?auction.startsAt:auction.endsAt,rule=auction.winnerMode==='highest'?'Побеждает максимальная ставка':'Победителя выбирает продавец',result=auction.status==='deal_confirmed'?'Сделка подтверждена':auction.status==='no_sale'?'Не продан':auction.status==='cancelled'?'Торги отменены':'Ожидается решение';const history=[...auction.bids].sort((a,b)=>new Date(a.createdAt)-new Date(b.createdAt));return`<article class="auction-card" data-auction-car="${escapeHtml(car.id)}"><div class="auction-card-image"><img src="${car.img}" alt="${escapeHtml(car.name)}"><span>⚡ ${scheduled?'Скоро':completed?'Завершён':active?'Аукцион':'Решение'}</span>${active||scheduled?`<b data-auction-countdown="${target}">${scheduled?'Старт через ':''}${auctionLeft(target)}</b>`:''}</div><div class="auction-card-body"><h3>${escapeHtml(car.name)}</h3><span class="auction-card-rule">${rule}</span><div class="auction-vehicle-facts"><span>${car.year} · ${escapeHtml(car.km)}</span><span>${escapeHtml(carEngineSummary(car))}</span><span>${escapeHtml(carTransmissionSummary(car))}</span></div><div class="auction-card-price"><span>${scheduled?'Стартовая цена':completed?'Итоговая цена':'Текущая ставка'}</span><strong>${money(auctionBest(auction))}</strong></div>${completed?`<div class="auction-card-result"><span>Результат</span><b>${result}</b></div><details class="bid-history-public"><summary>История цены · ${history.length}</summary><ol>${history.map((bid,index)=>`<li><span>Участник ${index+1}</span><b>${money(bid.amount)}</b></li>`).join('')||'<li>Ставок не было</li>'}</ol></details>`:`<div class="auction-card-meta"><span>${auction.bids.length} предложений</span><span>${scheduled?'Старт':'До завершения'}: ${auctionLeft(target)}</span></div>`}<button type="button">${active?'Участвовать в торгах':scheduled?'Напомнить о начале':'Открыть результат'} →</button></div></article>`}
function renderAuctionSection(){const unique=[...new Map(cars.filter(car=>car.auction).map(car=>[car.auction.id||car.listingId||car.id,car])).values()];unique.forEach(car=>{const auction=car.auction;if(auction.status==='scheduled'&&auction.startsAt<=Date.now())auction.status='active';if(auction.status==='active'&&auction.endsAt<=Date.now())auction.status=auction.bids.length&&(!auction.reservePrice||auctionBest(auction)>=auction.reservePrice)?'awaiting_seller':'no_sale'});const counts={};Object.entries(auctionTabStatuses).forEach(([key,statuses])=>counts[key]=unique.filter(car=>statuses.includes(car.auction.status)).length);document.querySelectorAll('[data-auction-tab]').forEach(button=>{button.classList.toggle('active',button.dataset.auctionTab===auctionTab);button.querySelector('span').textContent=counts[button.dataset.auctionTab]||0});const visible=unique.filter(car=>auctionTabStatuses[auctionTab].includes(car.auction.status));auctionGrid.innerHTML=visible.map(auctionCard).join('');auctionGrid.style.display=visible.length?'grid':'none';auctionEmpty.style.display=visible.length?'none':'flex'}
document.querySelector('#auctionTabs').addEventListener('click',event=>{const button=event.target.closest('[data-auction-tab]');if(!button)return;auctionTab=button.dataset.auctionTab;renderAuctionSection()});
auctionGrid.addEventListener('click',event=>{const card=event.target.closest('[data-auction-car]');if(!card)return;const car=cars.find(item=>String(item.id)===card.dataset.auctionCar);if(car){openDetail(car);renderAuction(car)}});
function persistAuctionCar(car){const own=JSON.parse(localStorage.getItem('vkluche-listings')||'[]'),index=own.findIndex(item=>String(item.id)===String(car.id));if(index>=0){own[index]=car;localStorage.setItem('vkluche-listings',JSON.stringify(own))}const overrides=JSON.parse(localStorage.getItem('vkluche-auction-overrides')||'{}');overrides[car.id]={auction:car.auction,price:car.price,badge:car.badge};localStorage.setItem('vkluche-auction-overrides',JSON.stringify(overrides))}
const auctionEventLabels={created:'Аукцион создан',status_changed:'Статус аукциона изменён',buyer_selected:'Продавец выбрал предложение',buyer_confirmed:'Покупатель подтвердил сделку',buyer_declined:'Покупатель отказался',buyer_response_expired:'Срок ответа покупателя истёк',no_sale:'Подходящих предложений не осталось',closed_without_sale:'Продавец завершил аукцион без сделки'};
function renderAuctionDeal(car){const auction=car.auction,box=document.querySelector('#auctionDeal');if(!auction||['scheduled','active'].includes(auction.status)){box.hidden=true;return}box.hidden=false;const deal=auction.deal,userId=window.vklucheAuth?.getUser()?.id,isSeller=canStartAuction(car),isBuyer=deal?.buyer_id===userId,statuses={awaiting_seller:['Торги завершены','Решение продавца'],awaiting_buyer:['Предложение выбрано','Ожидается покупатель'],deal_confirmed:['Сделка подтверждена','Подтверждено'],no_sale:['Аукцион завершён','Без сделки'],cancelled:['Аукцион отменён','Отменён']},[title,status]=statuses[auction.status]||['Результат аукциона','Завершено'];document.querySelector('#auctionDealTitle').textContent=title;document.querySelector('#auctionDealStatus').textContent=status;let text='';if(auction.status==='awaiting_seller')text=auction.bids.length?'Продавцу необходимо выбрать одно из предложений или завершить торги без сделки.':'На аукционе не было предложений.';if(auction.status==='awaiting_buyer')text=isBuyer?`Ваше предложение ${money(deal.amount)} выбрано. Ответьте до ${new Date(deal.response_deadline).toLocaleString('ru-RU')}.`:`Покупателю предложено подтвердить сделку на сумму ${money(deal?.amount||auctionBest(auction))}.`;if(auction.status==='deal_confirmed')text=`Покупатель подтвердил цену ${money(deal?.amount||auctionBest(auction))}. Следующий шаг — осмотр автомобиля и оформление договора.`;if(auction.status==='no_sale')text='Сделка по результатам торгов не состоялась. Автомобиль можно выставить повторно.';document.querySelector('#auctionDealText').textContent=text;const actions=[];if(auction.status==='awaiting_seller'&&isSeller)actions.push('<button type="button" data-close-auction>Завершить без сделки</button>');if(auction.status==='awaiting_buyer'&&isBuyer){actions.push('<button class="accept" type="button" data-deal-response="true">Подтвердить покупку</button>');actions.push('<button type="button" data-deal-response="false">Отказаться</button>')}document.querySelector('#auctionDealActions').innerHTML=actions.join('');const events=auction.events||[];document.querySelector('#auctionTimeline').innerHTML=events.length?events.map(item=>`<li><span>${auctionEventLabels[item.action]||'Событие аукциона'}</span><time>${new Date(item.created_at).toLocaleString('ru-RU')}</time></li>`).join(''):'<li><span>История появится после первого действия</span></li>'}
function renderAuction(car){
  const auction=car.auction,canManage=Boolean(car.listingId&&canStartAuction(car));document.querySelector('#mobilePrimaryAction').textContent=auction?'Сделать предложение':'Позвонить продавцу';document.querySelector('#startAuction').style.display=!auction&&canManage?'block':'none';document.querySelector('#archiveListing').style.display=canManage?'block':'none';document.querySelector('#listingOwnerTools').style.display=canManage?'flex':'none';auctionBox.style.display=auction?'block':'none';detail.classList.toggle('auction-active',Boolean(auction));document.querySelector('.finance-note').style.display=auction?'none':'block';
  refreshListingManagement(car);
  if(!auction)return;
  if(auction.status==='active'&&Date.now()>=auction.endsAt){auction.status=auction.bids.length?'awaiting_seller':'no_sale';persistAuctionCar(car)}
  const best=auctionBest(auction),active=auction.status==='active',statusLabel={awaiting_seller:'Выбор продавца',awaiting_buyer:'Ответ покупателя',deal_confirmed:'Сделка подтверждена',no_sale:'Без сделки',cancelled:'Отменён'}[auction.status]||'Торги завершены';document.querySelector('#detailPrice').textContent=money(best);document.querySelector('#auctionBest').textContent=money(best);document.querySelector('#auctionBidCount').textContent=auction.bids.length;document.querySelector('#auctionTimer').textContent=active?auctionLeft(auction.endsAt):auction.status==='scheduled'?`Старт через ${auctionLeft(auction.startsAt)}`:statusLabel;document.querySelector('#bidAmount').min=best+auction.bidStep;document.querySelector('#bidAmount').placeholder=new Intl.NumberFormat('ru-RU').format(best+auction.bidStep);bidForm.style.display=active?'grid':'none';
  const d=car.details||{},vehicleId=d.vin||d.identificationNumber||'Не указан',vehicleIdLabel=d.vin?'VIN':'Номер кузова/рамы',address=d.location?.address||car.city||'Не указан';document.querySelector('#auctionPassport').innerHTML=`<div><b>Паспорт лота</b><a href="#detailSpecs">Все характеристики</a></div><ul><li>${vehicleIdLabel} ${escapeHtml(vehicleId.length>7?`${vehicleId.slice(0,3)}••••${vehicleId.slice(-4)}`:vehicleId)}</li><li>${escapeHtml(address)}</li><li>${(d.images?.length||1)} фото</li><li>${(d.documents||[]).length} документов</li></ul>`;document.querySelector('#auctionRuleNote').textContent=auction.winnerMode==='highest'?'Побеждает максимальная ставка. После торгов покупатель должен подтвердить сделку в течение 24 часов.':'Продавец выбирает одно из предложений после завершения торгов. Максимальная ставка не гарантирует победу.';document.querySelector('#auctionWinnerHint').textContent=auction.winnerMode==='highest'?'После завершения будет автоматически выбрана максимальная ставка.':'После завершения продавец выберет подходящее предложение.';
  const bids=[...auction.bids].sort((a,b)=>b.amount-a.amount),mayChoose=canStartAuction(car)&&auction.status==='awaiting_seller'&&auction.winnerMode!=='highest',mayManage=canStartAuction(car)&&!['scheduled','active'].includes(auction.status);document.querySelector('#auctionBids').innerHTML=bids.length?bids.map((bid,index)=>`<div class="auction-bid ${auction.winnerId===bid.id?'winner':''}"><span><b>Участник ${index+1}</b><small>${escapeHtml(bid.comment||'Без комментария')}</small></span><strong>${money(bid.amount)}</strong>${mayChoose?`<button type="button" data-winner="${escapeHtml(bid.id)}">Выбрать предложение</button>`:' '}${mayManage&&auction.id?`<button class="participant-block" type="button" data-block-bid="${escapeHtml(bid.id)}">Ограничить участие</button>`:''}</div>`).join(''):'<p class="no-bids">Пока нет предложений</p>';
  renderAuctionDeal(car);
  if(auction.id){loadAuctionQuestions();loadAuctionInspections()}else{document.querySelector('#auctionQuestions').innerHTML='';document.querySelector('#auctionInspections').innerHTML=''}
}
let pendingBid=null;
async function placeConfirmedBid(){if(!pendingBid||!currentCar?.auction)return;const{auction,amount,comment,authUser}=pendingBid;pendingBid=null;closeBidConfirm();const button=bidForm.querySelector('[type="submit"]');button.disabled=true;if(auction.id){const{data,error}=await window.vklucheAuth.getClient().rpc('place_bid',{p_auction_id:auction.id,p_amount:amount,p_comment:comment});button.disabled=false;if(error)return toast(error.message);auction.bids.push({id:data.id,userId:authUser.id,buyer:'Участник',amount,comment,rating:5,createdAt:Date.now()})}else{button.disabled=false;auction.bids.push({id:`bid-${Date.now()}`,userId:authUser?.id,buyer:'Участник',amount,comment,rating:5,createdAt:Date.now()})}if(auction.autoExtend&&auction.endsAt-Date.now()<5*60*1000)auction.endsAt+=5*60*1000;currentCar.price=amount;bidForm.reset();persistAuctionCar(currentCar);renderAuction(currentCar);render();renderAuctionSection();toast('Предложение принято')}
bidForm.addEventListener('submit',async event=>{event.preventDefault();if(!currentCar?.auction)return;if(window.vklucheAuth&&!window.vklucheAuth.require(()=>{document.querySelector('#bidAmount').focus();toast('Теперь можно сделать предложение')}))return;const auction=currentCar.auction,amount=+document.querySelector('#bidAmount').value,best=auctionBest(auction);if(auction.status!=='active'||Date.now()>=auction.endsAt){auction.status=auction.bids.length?'awaiting_seller':'no_sale';renderAuction(currentCar);renderAuctionSection();return toast('Торги уже завершены')}if(amount<best+auction.bidStep)return toast(`Минимальная ставка — ${money(best+auction.bidStep)}`);const authUser=window.vklucheAuth?.getUser(),comment=document.querySelector('#bidComment').value.trim();pendingBid={auction,amount,comment,authUser};document.querySelector('#bidConfirmAmount').textContent=money(amount);document.querySelector('#bidConfirmNext').textContent=`После вашей ставки следующая минимальная цена — ${money(amount+auction.bidStep)}.`;document.querySelector('#bidConfirmRule').textContent=auction.winnerMode==='highest'?'Побеждает максимальная ставка.':'Победителя после окончания выбирает продавец.';const{data:profile}=await window.vklucheAuth.getClient().from('profiles').select('account_type,auction_verified,auction_wins,auction_declines,auction_ban_until').eq('id',authUser.id).maybeSingle();const total=(profile?.auction_wins||0)+(profile?.auction_declines||0),score=total?Math.round((profile.auction_wins/total)*100):100;document.querySelector('#bidParticipantStatus').textContent=`${profile?.auction_verified?'Профиль проверен':'Профиль не проверен'} · надёжность ${score}% · подтверждено сделок: ${profile?.auction_wins||0}`;bidConfirmModal.classList.add('open')});
document.querySelector('#auctionBids').addEventListener('click',async event=>{const blockButton=event.target.closest('[data-block-bid]');if(blockButton){if(!confirm('Ограничить этому участнику доступ к вашим аукционам на 30 дней?'))return;const{error}=await window.vklucheAuth.getClient().rpc('block_auction_participant',{p_auction_id:currentCar.auction.id,p_bid_id:blockButton.dataset.blockBid,p_days:30});return toast(error?error.message:'Участие ограничено на 30 дней')}const button=event.target.closest('[data-winner]');if(!button||!currentCar?.auction||!canStartAuction(currentCar))return;const bid=currentCar.auction.bids.find(item=>item.id===button.dataset.winner);let deal=null;if(currentCar.auction.id){button.disabled=true;const{data,error}=await window.vklucheAuth.getClient().rpc('select_auction_winner',{p_auction_id:currentCar.auction.id,p_bid_id:bid.id});button.disabled=false;if(error)return toast(error.message);deal=data}currentCar.auction.status='awaiting_buyer';currentCar.auction.winnerId=bid.id;currentCar.auction.deal=deal||{bid_id:bid.id,buyer_id:bid.userId,amount:bid.amount,status:'awaiting_buyer',response_deadline:new Date(Date.now()+24*60*60*1000).toISOString()};currentCar.price=bid.amount;currentCar.badge='Ожидается покупатель';persistAuctionCar(currentCar);renderAuction(currentCar);render();renderAuctionSection();toast('Покупателю отправлено предложение')});
document.querySelector('#auctionDeal').addEventListener('click',async event=>{const response=event.target.closest('[data-deal-response]'),close=event.target.closest('[data-close-auction]');if(!currentCar?.auction?.id||(!response&&!close))return;const button=response||close;button.disabled=true;let result;if(response)result=await window.vklucheAuth.getClient().rpc('respond_to_auction_offer',{p_deal_id:currentCar.auction.deal.id,p_accept:response.dataset.dealResponse==='true'});else result=await window.vklucheAuth.getClient().rpc('close_auction_without_sale',{p_auction_id:currentCar.auction.id});button.disabled=false;if(result.error)return toast(result.error.message);toast(response?.dataset.dealResponse==='true'?'Покупка подтверждена':response?'Отказ принят, предложение перейдёт следующему участнику':'Аукцион завершён без сделки');await loadRemoteListings();const refreshed=cars.find(car=>car.listingId===currentCar.listingId);if(refreshed){currentCar=refreshed;renderAuction(refreshed);render()}});
setInterval(()=>{if(currentCar?.auction&&detail.classList.contains('open'))renderAuction(currentCar);let expired=false;document.querySelectorAll('[data-auction-countdown]').forEach(timer=>{timer.textContent=auctionLeft(+timer.dataset.auctionCountdown);if(+timer.dataset.auctionCountdown<=Date.now())expired=true});if(expired)renderAuctionSection()},1000);
const photoInput=document.querySelector('#photoInput'),photoUpload=document.querySelector('#photoUpload'),preview=document.querySelector('#uploadPreview');function readPhotos(files){[...files].slice(0,10-uploadedPhotos.length).forEach(file=>{if(!file.type.startsWith('image/'))return;const reader=new FileReader();reader.onload=()=>{uploadedPhotos.push(reader.result);renderUploads()};reader.readAsDataURL(file)})}function renderUploads(){preview.innerHTML=uploadedPhotos.map((src,i)=>`<div><img src="${src}" alt="Фото автомобиля"><button type="button" data-remove-photo="${i}">×</button></div>`).join('')}photoInput.addEventListener('change',()=>readPhotos(photoInput.files));preview.addEventListener('click',e=>{const b=e.target.closest('[data-remove-photo]');if(b){uploadedPhotos.splice(+b.dataset.removePhoto,1);renderUploads()}});['dragenter','dragover'].forEach(n=>photoUpload.addEventListener(n,e=>{e.preventDefault();photoUpload.classList.add('drag')}));['dragleave','drop'].forEach(n=>photoUpload.addEventListener(n,e=>{e.preventDefault();photoUpload.classList.remove('drag')}));photoUpload.addEventListener('drop',e=>readPhotos(e.dataTransfer.files));document.querySelector('[name="price"]').addEventListener('input',e=>document.querySelector('#priceHint').textContent=e.target.value?`Покупатель увидит: ${money(+e.target.value)}`:'Укажите стоимость автомобиля');
const documentInput=document.querySelector('#documentInput'),documentPreview=document.querySelector('#documentPreview');function renderDocuments(){documentPreview.innerHTML=uploadedDocuments.map((document,index)=>`<div><span>📎</span><b>${escapeHtml(document.name)}</b><small>${Math.ceil(document.size/1024)} КБ</small><button type="button" data-remove-document="${index}" aria-label="Удалить">×</button></div>`).join('')}documentInput.addEventListener('change',()=>{const files=[...documentInput.files].slice(0,3-uploadedDocuments.length),currentSize=uploadedDocuments.reduce((sum,item)=>sum+item.size,0);files.forEach(file=>{if(currentSize+files.reduce((sum,item)=>sum+item.size,0)>4*1024*1024)return toast('Общий размер документов не должен превышать 4 МБ');const reader=new FileReader();reader.onload=()=>{uploadedDocuments.push({name:file.name,size:file.size,type:file.type,url:reader.result});renderDocuments()};reader.readAsDataURL(file)});documentInput.value=''});documentPreview.addEventListener('click',event=>{const button=event.target.closest('[data-remove-document]');if(!button)return;uploadedDocuments.splice(+button.dataset.removeDocument,1);renderDocuments()});
