async function loadRemoteListings(){
  const requestId=++remoteListingsRequest;
  const client=window.vklucheAuth?.getClient();if(!client)return;
  const{data,error}=await client.from('listings').select('id,owner_id,data,status,verification_status,verification_checks,vin,registration_plate,updated_at').eq('active',true).eq('status','published').order('updated_at',{ascending:false});
  if(error){if(requestId===remoteListingsRequest)console.warn(`Каталог Supabase пока недоступен: ${error.message}`);return}
  const remoteCars=[...new Map(data.map(row=>[row.id,{...row.data,listingId:row.id,ownerId:row.owner_id,updatedAt:row.updated_at,listingStatus:row.status,verificationStatus:row.verification_status,verificationChecks:row.verification_checks||{},details:{...(row.data.details||{}),vin:row.vin||row.data.details?.vin,registrationPlate:row.registration_plate||row.data.details?.registrationPlate}}])).values()];
  remoteCars.forEach(car=>{if(['automatic-feed','avito-feed'].includes(car.source)||car.date==='из фида'){car.date=publicCarDate(car);car.badge=publicCarBadge(car)}});
  const{data:auctionRows,error:auctionError}=await client.from('auctions').select('*,auction_bids!auction_bids_auction_id_fkey(*),auction_deals(*),auction_audit_log(*)').in('listing_id',data.map(row=>row.id));
  if(requestId!==remoteListingsRequest)return;
  if(auctionError)console.warn(`Аукционы пока недоступны: ${auctionError.message}`);
  (auctionRows||[]).forEach(row=>{const car=remoteCars.find(item=>item.listingId===row.listing_id);if(!car)return;const deals=[...(row.auction_deals||[])].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));car.auction={id:row.id,status:row.status,startPrice:+row.start_price,reservePrice:+row.reserve_price,bidStep:+row.bid_step,startsAt:new Date(row.starts_at).getTime(),endsAt:new Date(row.ends_at).getTime(),autoExtend:row.auto_extend,winnerMode:row.winner_mode||'seller_choice',participantAccess:row.participant_access||'all_verified',winnerId:row.winner_bid_id,deal:deals[0]||null,events:[...(row.auction_audit_log||[])].sort((a,b)=>new Date(a.created_at)-new Date(b.created_at)),bids:(row.auction_bids||[]).map(bid=>({id:bid.id,userId:bid.bidder_id,buyer:'Участник',amount:+bid.amount,comment:bid.comment,createdAt:new Date(bid.created_at).getTime()}))};car.price=auctionBest(car.auction);car.badge={scheduled:'Аукцион скоро',active:'Аукцион',awaiting_seller:'Выбор продавца',awaiting_buyer:'Ожидается покупатель',deal_confirmed:'Сделка подтверждена',no_sale:'Без сделки'}[row.status]||'Аукцион завершён'});
  const remoteListingIds=new Set(remoteCars.map(car=>car.listingId)),remoteCarIds=new Set(remoteCars.filter(car=>car.id!==undefined&&car.id!==null).map(car=>String(car.id)));
  for(let i=cars.length-1;i>=0;i--)if(cars[i].source==='automatic-feed'||cars[i].listingId||remoteCarIds.has(String(cars[i].id))||(Number.isInteger(cars[i].id)&&cars[i].id>=1&&cars[i].id<=8))cars.splice(i,1);
  const localListings=JSON.parse(localStorage.getItem('vkluche-listings')||'[]').filter(car=>!remoteListingIds.has(car.listingId)&&!remoteCarIds.has(String(car.id)));
  localStorage.setItem('vkluche-listings',JSON.stringify(localListings));
  cars.unshift(...remoteCars);document.querySelector('#liveListingCount').textContent=cars.length;document.querySelector('#catalogTrustLabel').textContent=`В каталоге ${cars.length} ${cars.length===1?'автомобиль':'автомобилей'}`;fillFilterCities();render();renderAuctionSection()
}
let realtimeChannel=null;function setupRealtime(){const client=window.vklucheAuth?.getClient(),user=window.vklucheAuth?.getUser();if(!client||!user)return;if(realtimeChannel)client.removeChannel(realtimeChannel);realtimeChannel=client.channel(`vkluche-auctions-${user.id}`).on('postgres_changes',{event:'*',schema:'public',table:'auctions'},()=>loadRemoteListings()).on('postgres_changes',{event:'INSERT',schema:'public',table:'auction_bids'},()=>loadRemoteListings()).on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications',filter:`user_id=eq.${user.id}`},()=>loadNotifications()).subscribe()}
function renderVehicleTrust(car){if(!car)return;const checksResult=car.verificationChecks||{},verified=car.verificationStatus==='verified',submitted=car.verificationStatus==='submitted',badge=document.querySelector('#verificationBadge');badge.className=verified?'verified':submitted?'submitted':'unverified';badge.textContent=verified?'Проверено ВКЛЮЧЕ':submitted?'Ожидает проверки':'Не проверено';document.querySelector('#verificationSummary').textContent=verified?'Результаты подтверждены площадкой или её партнёром.':submitted?'Данные переданы продавцом, но отметки появятся только после независимой проверки.':'Независимая проверка автомобиля ещё не проводилась.';const checks=[['Осмотр кузова',checksResult.body],['Техническая диагностика',checksResult.technical],['Проверка документов',checksResult.legal],['Проверка пробега',checksResult.mileage]];document.querySelector('#detailTrustChecks').innerHTML=checks.map(([label,ok])=>`<span class="${ok?'done':''}">${ok?'✓':'—'} ${label}${ok?'':' — не подтверждено'}</span>`).join('');document.querySelector('.detail-aside .seller span').textContent=verified?'Автомобиль проверен площадкой':'Данные продавца не проверены'}
new MutationObserver(()=>{if(detail.classList.contains('open'))renderVehicleTrust(currentCar)}).observe(detail,{attributes:true,attributeFilter:['class']});
document.querySelector('.sell-stats').innerHTML='<div><b>VIN</b><span>в карточке автомобиля</span></div><div><b>Онлайн</b><span>ставки на аукционе</span></div><div><b>0 ₽</b><span>базовое размещение</span></div>';document.querySelector('.seller-profile-stats div:first-child').innerHTML='<b>—</b><span>отзывов пока нет</span>';
async function persistRemoteFavorite(car){const client=window.vklucheAuth?.getClient(),user=window.vklucheAuth?.getUser();if(!client||!user||!car?.listingId)return;const active=saved.has(car.id),query=active?client.from('favorites').upsert({user_id:user.id,listing_id:car.listingId}):client.from('favorites').delete().eq('user_id',user.id).eq('listing_id',car.listingId);const{error}=await query;if(error)toast(error.message)}
async function syncRemoteFavorites(){const client=window.vklucheAuth?.getClient(),user=window.vklucheAuth?.getUser();if(!client||!user)return;const{data}=await client.from('favorites').select('listing_id');(data||[]).forEach(item=>{const car=cars.find(row=>row.listingId===item.listing_id);if(car)saved.add(car.id)});localStorage.setItem('vkluche-favs',JSON.stringify([...saved]));render()}
grid.addEventListener('click',event=>{const button=event.target.closest('.fav-btn');if(button){const car=cars.find(item=>String(item.id)===button.dataset.id);persistRemoteFavorite(car)}});document.querySelector('#detailFav').addEventListener('click',()=>persistRemoteFavorite(currentCar));
window.addEventListener('vkluche:open-listing',event=>{const car=cars.find(item=>item.listingId===event.detail?.listingId);if(!car)return toast('Объявление сейчас недоступно');document.querySelector('#authModal [data-auth-close]').click();openDetail(car);renderAuction(car)});document.querySelector('.favorite-top').addEventListener('click',()=>{if(!window.vklucheAuth?.require(()=>document.querySelector('.favorite-top').click()))return;window.vklucheAuth.open('profile');setTimeout(()=>window.dispatchEvent(new CustomEvent('vkluche:dashboard-tab',{detail:{tab:'favorites'}})),0)});
window.addEventListener('vkluche:profile',async()=>{await loadRemoteListings();await syncRemoteFavorites();setupRealtime()});document.querySelector('#liveListingCount').textContent=cars.length;fillFilterCities();render();renderAuctionSection();loadRemoteListings();setTimeout(setupRealtime,1000);
